pub fn define_class(
    vm: &mut Vm,
    intl: &Obj,
    name: &str,
    len: u32,
    ctor: NativeFn,
    members: &[Member],
    supported_locales: bool,
) -> (Obj, Obj) {
    let proto = vm.new_object();
    let c = vm.native_ctor(name, len, ctor, &proto);
    for m in members {
        match m {
            Member::Method(n, l, f) => {
                vm.def_method(&proto, n, *l, *f);
            }
            Member::Getter(n, f) => {
                vm.def_getter(&proto, n, *f);
