# Parse the original's grapheme signature sweep and classify each range.
rows = []
for line in open('/tmp/intlagent/seg/s8.out'):
    line = line.rstrip('\n')
    rng, *cols = line.split(' ')
    a, b = rng.split('..')
    rows.append((int(a, 16), int(b, 16), cols))

def classify(cols):
    aX, Xa, Xext, XXX, XzwjC, XV, XT, LX, VX, TX, CRX, XLF, PX, CzX, LVX, LVTX, KX = cols
    if CRX == '2':
        return 'LF'
    if XLF == '2':
        return 'CR'
    if Xext == '1,1':
        return 'Control'
    if XzwjC == '3' and CzX == '3':
        return 'ExtPict'
    if XXX == '2,1':
        return 'RI'
    if aX == '2':
        return 'ExtendLike'
    if Xa == '2':
        return 'Prepend'
    if XV == '2' and XT == '1,1':
        return 'L'
    if XV == '2' and XT == '2' and LX == '2':
        return 'V'  # or LV? LV + V -> joined, L + LV joined... distinguish below
    if XT == '2' and LX == '2':
        return 'LVT_or_LV'
    if XT == '2':
        return 'T'
    return 'Other'

out = {}
for a, b, cols in rows:
