        my $v;
        if ($cp >= 0xD800 && $cp <= 0xDFFF) { $v = 'SURR'; }
        else {
            my $c = chr($cp);
            no warnings;
            $v = Unicode::UCD::charprop($cp, $p);
        }
        $v //= '';
        if (!defined $prev) { $prev = $v; $start = $cp; next; }
        if ($v ne $prev) { printf "%s %x %x %s\n", $p, $start, $cp - 1, $prev; $prev = $v; $start = $cp; }
    }
    printf "%s %x %x %s\n", $p, $start, 0x10FFFF, $prev;
}
