    for my $cp (0 .. 0x10FFFF) {
        my $v;
        if ($cp >= 0xD800 && $cp <= 0xDFFF) { $v = 'N'; }
        else { $v = (chr($cp) =~ /\p{Extended_Pictographic}/) ? 'Y' : 'N'; }
        if (!defined $prev) { $prev = $v; $start = $cp; next; }
