        my $e = ($i < $#$list) ? $list->[$i + 1] - 1 : 0x10FFFF;
        my $v = $map->[$i];
        $v = join('|', @$v) if ref $v;
        printf "%s %x %x %s\n", $p, $s, $e, $v;
    }
