// ---------------------------------------------------------------------------
// General category
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum GeneralCategory {
    Lu,
    Ll,
    Lt,
    Lm,
    Lo,
    Mn,
    Mc,
    Me,
    Nd,
    Nl,
    No,
    Pc,
    Pd,
    Ps,
    Pe,
    Pi,
    Pf,
    Po,
    Sm,
    Sc,
    Sk,
    So,
    Zs,
    Zl,
    Zp,
    Cc,
    Cf,
    Cs,
    Co,
    Cn,
}

const GC_ALL: [GeneralCategory; 30] = {
    use GeneralCategory::*;
    [
        Lu, Ll, Lt, Lm, Lo, Mn, Mc, Me, Nd, Nl, No, Pc, Pd, Ps, Pe, Pi, Pf, Po, Sm, Sc, Sk, So, Zs,
        Zl, Zp, Cc, Cf, Cs, Co, Cn,
    ]
};

impl GeneralCategory {
    /// Two-letter short name (e.g. "Lu").
    pub fn short_name(self) -> &'static str {
        tables::GC_ORDER[self as usize]
    }
}

/// Partition of the code space: (start, category index); sorted, first start is 0.
fn gc_table() -> &'static [(u32, u8)] {
    static T: OnceLock<Vec<(u32, u8)>> = OnceLock::new();
    T.get_or_init(|| {
        let mut r = Reader::new(tables::GC_DATA);
